import numpy as np

class ExtremeLearningMachine:
    def __init__(self, input_dim, hidden_dim, alpha=1e-5):
        self.hidden_dim = hidden_dim
        self.alpha = alpha  # Regularisation parameter (L2)
        # Randomly initialize and freeze hidden weights and biases
        self.W = np.random.normal(size=(input_dim, hidden_dim))
        self.b = np.random.normal(size=(1, hidden_dim))
        self.beta = None

    def _activate(self, X):
        # Sigmoid activation function
        return 1 / (1 + np.exp(-(np.dot(X, self.W) + self.b)))

    def fit(self, X, y):
        H = self._activate(X)
        # Solve for output weights analytically using Ridge regression
        I = np.eye(self.hidden_dim)
        self.beta = np.linalg.solve(H.T @ H + self.alpha * I, H.T @ y)

    def predict(self, X):
        H = self._activate(X)
        return H @ self.beta
